-- V39: extend existing V1 expense, expense_category, provider and cash_movement.
CREATE SEQUENCE IF NOT EXISTS expense_reference_seq;
CREATE SEQUENCE IF NOT EXISTS expense_category_code_seq;
CREATE SEQUENCE IF NOT EXISTS expense_provider_code_seq;
ALTER TABLE expense ADD COLUMN IF NOT EXISTS paid_amount NUMERIC(14,2) NOT NULL DEFAULT 0;
ALTER TABLE expense ADD COLUMN IF NOT EXISTS rejected_reason TEXT;
ALTER TABLE expense ADD CONSTRAINT ck_v39_expense_paid CHECK (paid_amount >= 0 AND paid_amount <= amount);
CREATE TABLE expense_payment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES expense(id), reference VARCHAR(80) UNIQUE, amount NUMERIC(14,2) NOT NULL CHECK(amount > 0), payment_method VARCHAR(40) NOT NULL, cash_register_session_id BIGINT REFERENCES cash_register_session(id), paid_by BIGINT NOT NULL REFERENCES user_account(id), paid_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE expense_attachment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, expense_id BIGINT NOT NULL REFERENCES expense(id), filename VARCHAR(255) NOT NULL, storage_key TEXT NOT NULL, mime_type VARCHAR(120), uploaded_by BIGINT NOT NULL REFERENCES user_account(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE expense_budget (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id BIGINT NOT NULL REFERENCES expense_category(id), year INTEGER NOT NULL, month INTEGER NOT NULL CHECK(month BETWEEN 1 AND 12), amount NUMERIC(14,2) NOT NULL CHECK(amount >= 0), UNIQUE(category_id,year,month));
ALTER TABLE cash_movement ADD COLUMN IF NOT EXISTS expense_payment_id BIGINT REFERENCES expense_payment(id);
CREATE UNIQUE INDEX IF NOT EXISTS ux_cash_movement_expense_payment ON cash_movement(expense_payment_id) WHERE expense_payment_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_v39_expense_date_category ON expense(expense_date,expense_category_id);
CREATE INDEX IF NOT EXISTS idx_v39_expense_payment_expense ON expense_payment(expense_id);
INSERT INTO expense_category(code,name,active) SELECT 'V39-'||lpad(n::text,2,'0'),name,TRUE FROM (VALUES (1,'Restauration scolaire'),(2,'Ménage et entretien'),(3,'Salaires enseignants'),(4,'Salaires personnel'),(5,'Loyer'),(6,'Factures et abonnements'),(7,'Fournitures administratives'),(8,'Matériel pédagogique'),(9,'Informatique'),(10,'Transport scolaire'),(11,'Maintenance et réparations'),(12,'Équipements et mobilier'),(13,'Activités scolaires'),(14,'Communication et publicité'),(15,'Assurances, cotisations et taxes'),(16,'Autres dépenses')) v(n,name) WHERE NOT EXISTS (SELECT 1 FROM expense_category ec WHERE lower(ec.name)=lower(v.name));
INSERT INTO permission(code,name,module,description,active) SELECT p.code,p.name,'FINANCE',p.name,TRUE FROM (VALUES ('DEPENSES_CONSULTER','Consulter les dépenses'),('DEPENSES_GERER','Gérer les dépenses'),('DEPENSES_VALIDER','Valider les dépenses'),('DEPENSES_PAYER','Payer les dépenses'),('DEPENSES_RAPPORTS','Rapports des dépenses')) p(code,name) WHERE NOT EXISTS(SELECT 1 FROM permission x WHERE x.code=p.code);
